#pragma once

#include "CoreMinimal.h"

/**
 * Values from reverse engineering of the game. Num's default is the value itself; Data/regras.json (optional,
 * generated by tools/make_rules.py from the local cache re-local/) only overrides it.
 */
struct NWPORT_API FNWRules
{
	/** The fact's value; Default (with a log warning, once) if the id is not in Data/regras.json. */
	static double Num(const TCHAR* Id, double Default);
};
